style.css:
@-moz-document domain("roblox.com") {
/* General background (keep your pink theme) */
    body, .content, .container, .game-home-page {
        background-color: #f6b5c5 !important;
    }

    /* Sidebar pink accent */
    .menu-vertical, .side-nav, .left-col, .navigation-container {
        background-color: #f2789f !important;
    }

    /* Navbar */
    .nav-container, .navbar, header {
        background-color: #f08ba5 !important;
    }

    /* Play button styling */
    button[aria-label="Play"],
    .btn-common-playgame,
    .play-button,
    .play-button .btn-primary {
        background-color: #b00030 !important; /* Cherry red base */
        color: white !important;
        border: none !important;
        border-radius: 12px !important;
        transition: all 0.3s ease-in-out !important;
        box-shadow: 0 0 10px rgba(255, 153, 185, 0.4);
    }

    /* Hover + Glow animation */
    button[aria-label="Play"]:hover,
    .btn-common-playgame:hover,
    .play-button:hover {
        background-color: #d4145a !important;
        box-shadow: 0 0 20px #ff99b9, 0 0 30px #ff99b9;
        transform: scale(1.05);
        animation: pulseGlow 1.5s infinite alternate;
    }

    /* Animation keyframes */
    @keyframes pulseGlow {
        from {
            box-shadow: 0 0 10px #ff99b9, 0 0 20px #ff99b9;
        }
        to {
            box-shadow: 0 0 25px #ff99b9, 0 0 40px #ff99b9;
        }
    }

    /* Fix text visibility */
    h1, h2, h3, h4, h5, p, span, a {
        color: #2e2e2e !important;
    }
}
